# GENERATED by scripts/sync_hems_core.py from hems/core/hems/executor.py; do not edit here.
"""Executor: the last check between the planner's command and a device.

The planner decides the shape of the day from forecasts (charge in the cheap window, sell from the charged energy
later) and is replanned every quarter from the actual SoC. The executor runs at the moment of action and on every
SoC update in between: it re-checks the live SoC and never lets the command run the battery below its floor, past
full, or on a SoC it cannot trust. Pure (no I/O, no clock): the caller supplies `now` and the reading.
"""
from dataclasses import dataclass
from datetime import datetime, timedelta

from .battery import BatteryConfig, floor_fraction
from .contracts import Reading
from .rolling import Decision

AS_PLANNED = "as_planned"        # the command passes unchanged
NO_PLAN = "no_plan"              # the planner has no decision (its status says why); nothing is sent
EXPIRED = "expired"              # the decision's quarter is not the current one and no replan arrived: hold
NO_SOC = "no_soc"                # no SoC reading: a charge or discharge command is held
STALE_SOC = "stale_soc"          # the SoC stopped updating: the command is held
AT_FLOOR = "at_floor"            # discharge refused: the SoC is at the floor (reserve or hard minimum)
LIMITED_FLOOR = "limited_floor"  # discharge slowed to what is left above the floor for the rest of the quarter
AT_FULL = "at_full"              # charge refused: the battery is full
LIMITED_FULL = "limited_full"    # charge slowed to the room left for the rest of the quarter

EXPIRY_GRACE = timedelta(seconds=90)   # the replan runs 20 s past the boundary: the old command is not 'expired' while it is on its way
MIN_ACTION_W = 50                # below this a limited command is rounded to hold
ROUNDING_W = 10                  # a command this close to its cap is the planner's own rounding of the same limit, not an override
MIN_REMAINING_H = 1 / 60         # the last minute of a quarter must not turn the remaining-energy cap into a huge power


@dataclass(frozen=True)
class Execution:
    """What may be sent now (+ charge / - discharge, AC side) and what the planner wanted."""
    power_w: int
    planned_w: int
    code: str
    reason: str
    soc_pct: float | None = None

    @property
    def overridden(self) -> bool:
        """True when the executor changed the planner's power."""
        return self.power_w != self.planned_w


def _held(planned_w: int, code: str, reason: str, soc_pct: float | None = None) -> Execution:
    """An override to hold (0 W)."""
    return Execution(0, planned_w, code, reason, soc_pct)


@dataclass(frozen=True)
class _Guard:
    """The two outcomes of a limit check: slowed to the cap, or refused because (almost) nothing is left."""
    limited: str
    refused: str


@dataclass(frozen=True)
class _Check:
    """A command against the energy that is left: planned power, the power the rest of the quarter allows, the live SoC."""
    planned_w: int
    cap_w: float
    soc_pct: float
    label: str                       # what limits the command, for the reason text ("floor 30%", "full")


FLOOR_GUARD = _Guard(LIMITED_FLOOR, AT_FLOOR)
FULL_GUARD = _Guard(LIMITED_FULL, AT_FULL)


def _apply(check: _Check, guard: _Guard) -> Execution:
    """Pass the command within the cap, slow it to the cap, or hold when almost nothing is left."""
    planned_w, cap_w, soc_pct = check.planned_w, check.cap_w, check.soc_pct
    if abs(planned_w) <= cap_w + ROUNDING_W:
        return Execution(planned_w, planned_w, AS_PLANNED, "within the live SoC", soc_pct)
    if cap_w < MIN_ACTION_W:
        return _held(planned_w, guard.refused, f"{check.label}: SoC {soc_pct:.1f}%, nothing left to move", soc_pct)
    power = int(cap_w) * (1 if planned_w > 0 else -1)
    return Execution(power, planned_w, guard.limited, f"{check.label}: SoC {soc_pct:.1f}%, {abs(planned_w)} W slowed to {abs(power)} W", soc_pct)


def _discharge_floor(decision: Decision, cfg: BatteryConfig) -> float:
    """The floor a discharge may run to: the sell floor for a sale, the hard minimum when the battery only covers the house."""
    slot = decision.slots[0] if decision.slots else None
    planned = decision.plan.slots[0] if decision.plan.slots else None
    return floor_fraction(slot, cfg) if planned is None or planned.action == "discharge" else cfg.hard_min_soc


def execute(decision: Decision | None, now: datetime, soc: Reading | None, cfg: BatteryConfig,
            max_soc_age: timedelta = timedelta(minutes=15)) -> Execution:
    """Check the planner's command for this quarter against the live SoC and return what may be sent.

    A command that is already idle always passes. A charge or discharge is held when there is no trustworthy SoC
    or the decision is not for the current quarter, and is refused or slowed when the live SoC leaves no room."""
    if decision is None:
        return _held(0, NO_PLAN, "no decision from the planner")
    command = decision.command
    planned_w = round(command.power_w)
    if planned_w == 0:
        return Execution(0, 0, AS_PLANNED, "idle", None if soc is None else soc.value)
    if not command.start <= now < command.end + EXPIRY_GRACE:
        return _held(planned_w, EXPIRED, f"decision for {command.start.isoformat()} is not for now")
    if soc is None:
        return _held(planned_w, NO_SOC, "no SoC reading")
    if not soc.is_fresh(now, max_soc_age):
        return _held(planned_w, STALE_SOC, f"SoC is {round(soc.age(now).total_seconds())} s old")
    # The room is measured at the moment the SoC last changed, so the time left runs from then too. Measured from `now`, a
    # SoC that stays at the same number for a minute (the battery keeps charging) would show a limit that rises with the clock
    # until the next tick pulls it down again: the command would flap between limited and as planned every minute.
    reference = min(max(soc.known_since, command.start), now)
    remaining_h = max((command.end - reference).total_seconds() / 3600, MIN_REMAINING_H)
    eff = cfg.round_trip_eff ** 0.5
    if planned_w < 0:
        floor_pct = _discharge_floor(decision, cfg) * 100
        above_kwh = max(0.0, (soc.value - floor_pct) / 100 * cfg.capacity_kwh)
        return _apply(_Check(planned_w, above_kwh * eff / remaining_h * 1000, soc.value, f"floor {floor_pct:.0f}%"), FLOOR_GUARD)
    room_kwh = max(0.0, (cfg.max_soc * 100 - soc.value) / 100 * cfg.capacity_kwh)
    return _apply(_Check(planned_w, room_kwh / eff / remaining_h * 1000, soc.value, "full"), FULL_GUARD)
